script:
// Forgó vezetőkeret homogén mágneses térben – 3D nézet
// Rotating loop in a uniform magnetic field – 3D view
//   Φ = B·A·cos α  (α: az n normálvektor és B szöge, α = θ + 90°)      u = −N·dΦ/dt = N·B·A·ω·cos θ
// 3D tengelyek: x jobbra (a tér iránya), y felfelé, z a forgástengely / 3D axes: x right (field), y up, z = rotation axis

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Forgó vezetőkeret mágneses térben", en: "Rotating loop in a magnetic field"});
// Kezdő lassítás (a Sebesség csúszkán állítható) / Initial slow motion (change it on the Speed slider)
timeScale(0.025);
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(3);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("n",     {hu: "Fordulatszám n", en: "Speed n"}, 0, 300, 60, 1, "1/min");
param("B",     {hu: "Mágneses indukció B", en: "Flux density B"}, 0, 1.5, 0.8, 0.01, "T");
param("N",     {hu: "Menetszám N", en: "Number of turns N"}, 1, 500, 100, 1, "");
param("A",     {hu: "Keret felülete A", en: "Loop area A"}, 10, 400, 100, 1, "cm²");
param("yaw",   {hu: "Nézet: elforgatás", en: "View: turn"}, -90, 90, -38, 1, "°");
param("pitch", {hu: "Nézet: dőlés", en: "View: tilt"}, -30, 70, 20, 1, "°");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("field", {hu: "Erővonalak", en: "Field lines"}, true);
toggle("cur",   {hu: "Indukált áram iránya", en: "Direction of the induced current"}, true);
toggle("vec",   {hu: "Normálvektor és sebesség", en: "Normal vector and velocity"}, true);

let th = 0, u = 0, curPos = 0, fieldPos = 0;

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => {
  const w = P.n * PI / 30;
  th += w * dt;
  u = P.N * P.B * P.A * 1e-4 * w * cos(th);
  curPos += -2.2 * cos(th) * sign(w) * dt;   // v × B: az „A” oldalon −z irányú, ha cos θ > 0 / along −z on side A when cos θ > 0
  fieldPos += 1.2 * P.B * dt;
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  // 3D nézet: középpont, lépték (px/egység), elforgatás, dőlés / 3D view: centre, scale (px per unit), turn, tilt
  view3d({x: 480, y: 335, scale: 82, yaw: deg(P.yaw), pitch: deg(P.pitch), dist: 16});
  // Innentől a 3D elemek mélység szerint rendeződnek / From here, 3D items are depth-sorted
  begin3();
  // Pólusok / poles
  box3([-3.5, 0, 0], [1.3, 3.4, 4.0], {fill: C.N});
  box3([3.5, 0, 0], [1.3, 3.4, 4.0], {fill: C.S});
  text3("N", [-3.5, 2.4, 0], {size: 28, bold: true, color: C.N, align: "center"});
  text3("S", [3.5, 2.4, 0], {size: 28, bold: true, color: C.S, align: "center"});

  // Erővonalak N-től S felé / field lines from N to S
  if (P.field && P.B > 0.001) {
    for (const y of [-1.2, 0, 1.2]) for (const z of [-1.4, 0, 1.4]) {
      const fl = [[-2.85, y, z], [2.85, y, z]];
      path3(fl, {stroke: "#c8963e", lw: 1.3, alpha: 0.75});
      flow3(fl, {pos: fieldPos, dir: 1, spacing: 1.9, size: 9, color: "#e0663a", id: "erővonal"});
    }
  }

  // Tengely és keret: a keret oldalai a z tengellyel párhuzamosak / shaft and loop: the sides run parallel to z
  wire3([[0, 0, -2.6], [0, 0, 2.9]], {color: "#9aa3b1", lw: 6});
  const a = 1.05, L = 1.55, c = cos(th), s = sin(th);
  // A keret négy sarka; θ szöggel elforgatva a z tengely körül / the loop’s four corners, turned by θ about z
  const loop = [[a * c, a * s, -L], [a * c, a * s, L], [-a * c, -a * s, L], [-a * c, -a * s, -L]];
  wire3(loop, {color: C.orange, lw: 9}, true);
  text3("A", [a * c * 1.3, a * s * 1.3, -L], {size: 16, bold: true, color: C.orange});

  if (P.cur && P.n > 0) {
    const al = clamp(abs(c) * 2, 0, 1);
    if (al > 0.05) flow3(loop, {pos: curPos, dir: -sign(c), spacing: 1.1, size: 13, color: C.blue, alpha: al, id: "indukált áram"}, true);
  }
  if (P.vec) {
    arrow3([0, 0, 0], [-1.7 * s, 1.7 * c, 0], {stroke: C.purple, lw: 3, id: "normálvektor n"});
    text3("n", [-1.95 * s, 1.95 * c, 0], {size: 18, bold: true, italic: true, color: C.purple});
    if (P.n > 0) {
      arrow3([a * c, a * s, 0], [a * c - 0.9 * s, a * s + 0.9 * c, 0], {stroke: C.green, lw: 3, id: "sebesség v"});
      text3("v", [a * c - 1.15 * s, a * s + 1.15 * c, 0], {size: 18, bold: true, italic: true, color: C.green});
    }
  }
  // A 3D elemek kirajzolása (a távoliak előbb) / Draw the 3D items (far ones first)
  end3();

  text({hu: "u akkor a legnagyobb, amikor Φ = 0: a keret oldalai ekkor metszik a legtöbb erővonalat",
        en: "u peaks when Φ = 0: that is when the sides cut the most field lines"}, 22, 64, {size: 13, color: C.gray});

  const w = P.n * PI / 30, Phi = -P.B * P.A * 1e-4 * sin(th);
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Elfordulás θ", en: "Angle θ"}, todeg(mod(th, 2 * PI)), "°");
  show({hu: "Fluxus Φ", en: "Flux Φ"}, Phi * 1000, "mWb");
  show({hu: "Indukált feszültség u", en: "Induced voltage u"}, u, "V");
  show({hu: "Csúcsérték Û = N·B·A·ω", en: "Peak value Û = N·B·A·ω"}, P.N * P.B * P.A * 1e-4 * w, "V");
  show({hu: "Frekvencia f = n/60", en: "Frequency f = n/60"}, P.n / 60, "Hz");
  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Fluxus Φ", en: "Flux Φ"}, Phi * 1000, {unit: "mWb", color: C.purple});
  plot({hu: "Feszültség u", en: "Voltage u"}, u, {unit: "V", color: C.blue});
});
